#!/usr/bin/env bash
# cookbook/plc-st/media/make_media.sh
# Builds result.png, loop.png, demo.mp4 from judge output data.
# Uses pinned pip versions and ffmpeg from distro.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
JUDGE_DIR="${HERE}/../judge"
GOOD_ST="${HERE}/../examples/good/tank_ctrl.st"
DATA_DIR="${HERE}/data"

# Judge output data (verdict JSONs, selftest log, trace CSVs) must exist;
# it is generated by make_data.sh and committed to git.
[ -d "${DATA_DIR}" ] || { echo "run media/make_data.sh first"; exit 1; }

# Pinned Python packages
MATPLOTLIB_VERSION="3.8.4"
NUMPY_VERSION="1.26.4"
PILLOW_VERSION="10.3.0"

# ffmpeg from distro (Debian bookworm: ffmpeg 5.1.6-0+deb12u1)
# Verify ffmpeg is available
command -v ffmpeg >/dev/null || { echo "ffmpeg not found; install it first"; exit 1; }

# Create venv with pinned packages
VENV="${HERE}/.venv"
if [ ! -d "${VENV}" ]; then
    python3 -m venv "${VENV}"
    "${VENV}/bin/pip" install --no-cache-dir \
        "matplotlib==${MATPLOTLIB_VERSION}" \
        "numpy==${NUMPY_VERSION}" \
        "pillow==${PILLOW_VERSION}"
fi

# Generate the plots
"${VENV}/bin/python" "${HERE}/make_plots.py"

# Build the video from frames
# First, generate frames (lossless master)
mkdir -p "${HERE}/master"
"${VENV}/bin/python" "${HERE}/make_frames.py"

# Encode to H.264 web version
ffmpeg -y -hide_banner -loglevel error \
    -framerate 30 -i "${HERE}/master/frame_%04d.png" \
    -c:v libx264 -preset slow -crf 18 -pix_fmt yuv420p \
    -vf "scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2" \
    -movflags +faststart \
    "${HERE}/demo.mp4"

# Also create a lossless master archive (git-ignored)
ffmpeg -y -hide_banner -loglevel error \
    -framerate 30 -i "${HERE}/master/frame_%04d.png" \
    -c:v libx264 -preset ultrafast -crf 0 -pix_fmt yuv420p \
    "${HERE}/master/demo_master.mkv"

# Verify output
echo "=== Media verification ==="
ls -la "${HERE}/result.png" "${HERE}/loop.png" "${HERE}/demo.mp4"
ffprobe -v error -select_streams v:0 -show_entries stream=width,height,codec_name,duration -of csv=p=0 "${HERE}/demo.mp4"

# Generate MANIFEST.json
"${VENV}/bin/python" -c "
import json, hashlib, os, subprocess, sys
manifest = {}
for fname in ['result.png', 'loop.png', 'demo.mp4']:
    path = os.path.join('${HERE}', fname)
    with open(path, 'rb') as f:
        manifest[fname] = {'sha256': hashlib.sha256(f.read()).hexdigest(), 'size': os.path.getsize(path)}
# Source data files: everything under media/data/ (verdict JSONs, selftest
# log, trace CSVs) generated by make_data.sh, relative to media/.
for root, dirs, files in sorted(os.walk('${DATA_DIR}')):
    for fname in sorted(files):
        path = os.path.join(root, fname)
        rel = os.path.relpath(path, '${HERE}')
        with open(path, 'rb') as f:
            manifest[rel] = {'sha256': hashlib.sha256(f.read()).hexdigest(), 'size': os.path.getsize(path)}
# Add command
manifest['command'] = 'bash make_data.sh && bash make_media.sh'
manifest['ffmpeg_version'] = subprocess.run(['ffmpeg', '-version'], capture_output=True, text=True).stdout.split('\n')[0]
with open(os.path.join('${HERE}', 'MANIFEST.json'), 'w') as f:
    json.dump(manifest, f, indent=2)
print('MANIFEST.json written')
"

# Print sha256sums
sha256sum "${HERE}/result.png" "${HERE}/loop.png" "${HERE}/demo.mp4" "${HERE}/MANIFEST.json"